const raw = items[0].json;
const report = raw.report;

if (report.error) {
  return [{
    json: {
      success: false,
      error: report.error,
      timestamp: new Date().toISOString()
    }
  }];
}

// Calcul de métriques de synthèse
const topUsage = report.top_usage || [];
const critical = report.critical_stations || [];
const live = report.live_snapshot || [];

const totalBikes = live.reduce((sum, s) => sum + (s.bikes_available || 0), 0);
const totalSlots = live.reduce((sum, s) => sum + (s.free_slots || 0), 0);
const emptyStations = live.filter(s => s.bikes_available === 0).length;
const fullStations = live.filter(s => s.free_slots === 0).length;

return [{
  json: {
    success: true,
    generated_at: new Date().toISOString(),
    data_range: report.data_range,
    summary: {
      total_stations_live: live.length,
      total_bikes_available: totalBikes,
      total_slots_available: totalSlots,
      empty_stations: emptyStations,
      full_stations: fullStations,
      global_usage_pct: totalBikes + totalSlots > 0
        ? Math.round(totalBikes / (totalBikes + totalSlots) * 100 * 10) / 10
        : null
    },
    top_usage: topUsage,
    insufficient_zones: report.insufficient_zones || [],
    daily_peaks: report.daily_peaks || [],
    geographic_imbalances: report.geographic_imbalances || [],
    critical_stations: critical,
    live_snapshot: live
  }
}];
